R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_ktrev; cp $R/sb_cursor_probe/AGENTS.md $R/sb_ktrev/AGENTS.md
echo  | base64 -d > $R/sb_ktrev/PROMPT.md
cd $R/sb_ktrev && tmux new-session -d -s sb_ktrev "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "
